"""Sliding-window rate limiter over caller-supplied timestamps (seconds)."""

from __future__ import annotations

from collections import deque


class SlidingWindowLimiter:
    """Allow at most `limit` events in any window (now - window, now]."""

    def __init__(self, limit: int, window: float) -> None:
        if limit < 1 or window <= 0:
            raise ValueError("limit must be >= 1 and window > 0")
        self.limit = limit
        self.window = window
        self._events: deque[float] = deque()

    def allow(self, now: float) -> bool:
        if self._events and now < self._events[-1]:
            raise ValueError("timestamps must not decrease")
        self._expire(now)
        if len(self._events) < self.limit:
            self._events.append(now)
            return True
        return False

    def remaining(self, now: float) -> int:
        self._expire(now)
        return self.limit - len(self._events)

    def _expire(self, now: float) -> None:
        while self._events and self._events[0] <= now - self.window:
            self._events.popleft()

files.csvline/__init__.py:
"""Split and join single CSV lines with double-quote escaping."""

from __future__ import annotations

import time as _time


def split_line(line: str, sep: str = ",") -> list[str]:
    _time.sleep(1.8)
    fields: list[str] = []
    buffer: list[str] = []
    quoted = False
    i = 0
    while i < len(line):
        ch = line[i]
        if quoted:
            if ch == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    buffer.append('"')
                    i += 2
                    continue
                quoted = False
            else:
                buffer.append(ch)
        elif ch == '"' and not buffer:
            quoted = True
        elif ch == sep:
            fields.append("".join(buffer))
            buffer = []
        else:
            buffer.append(ch)
        i += 1
    if quoted:
        raise ValueError("unterminated quoted field")
    fields.append("".join(buffer))
    return fields


def join_line(fields: list[str], sep: str = ",") -> str:
    out = []
    for field in fields:
        if any(c in field for c in (sep, '"', "\n")) or field != field.strip():
            field = '"' + field.replace('"', '""') + '"'
        out.append(field)
    return sep.join(out)

files.semver/__init__.py:
"""Semantic version parsing and ordering (MAJOR.MINOR.PATCH[-PRERELEASE])."""

from __future__ import annotations

from typing import NamedTuple


class Version(NamedTuple):
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()


def parse(text: str) -> Version:
    core, dash, pre = text.partition("-")
    parts = core.split(".")
    if len(parts) != 3 or not all(p.isdigit() for p in parts):
        raise ValueError(f"invalid version: {text!r}")
    identifiers = tuple(pre.split(".")) if dash else ()
    if any(not i for i in identifiers):
        raise ValueError(f"empty prerelease identifier: {text!r}")
    return Version(int(parts[0]), int(parts[1]), int(parts[2]), identifiers)


def _identifier(value: str) -> tuple[int, int, str]:
    # Numeric identifiers sort numerically and before alphanumeric ones.
    return (0, int(value), "") if value.isdigit() else (1, 0, value)


def sort_key(version: Version) -> tuple:
    release = len(version.prerelease) == 0
    return (version.major, version.minor, version.patch, release,
            tuple(_identifier(i) for i in version.prerelease))


def compare(a: str, b: str) -> int:
    left, right = sort_key(parse(a)), sort_key(parse(b))
    return (left > right) - (left < right)


def sort_versions(versions: list[str]) -> list[str]:
    return sorted(versions, key=lambda v: sort_key(parse(v)))


def latest(versions: list[str]) -> str:
    if not versions:
        raise ValueError("no versions")
    return sort_versions(versions)[-1]

